private void ShtoRreshtaNeTabele2(XRTable xrTable2)
{
	int i = 0;
	if (dt.Rows.Count > 0)
	{
		for (int j = xrTable12.Rows.Count - 1; j >= 1; j--)
		{
			xrTable12.Rows.RemoveAt(j);
		}
		Font arial = new Font("Century Gothic", 9.00F, FontStyle.Regular);
		PaddingInfo padding = new PaddingInfo(2, 2, 0, 0);
		BorderSide borders = ((BorderSide)((BorderSide.Left | BorderSide.Bottom )));
		BorderSide borderLast = ((BorderSide)((BorderSide.Left | BorderSide.Bottom | BorderSide.Right )));
		foreach (System.Data.DataRow row in dt.Rows)
           	{ 
			if(Convert.ToInt32(row["grup2"]) == 2)
			{
	                    XRTableRow rr = new XRTableRow();
	                    rr.HeightF = 20f;

	                    XRTableCell nr = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(43.27f, "", (i + 1).ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
	                    rr.Cells.Add(nr);

	                    XRTableCell nrdok= AlphaWebReports.raporteUtil.shtoQelizeNeTabele(76.89f,  "", row["NRDOK"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
	                    rr.Cells.Add(nrdok);

	                    XRTableCell nrserial= AlphaWebReports.raporteUtil.shtoQelizeNeTabele(70.64f,  "", row["NRSERIAL"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
	                    rr.Cells.Add(nrserial);

	                    XRTableCell kodmag= AlphaWebReports.raporteUtil.shtoQelizeNeTabele(79.49f, "", row["kodmagazina"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
	                    rr.Cells.Add(kodmag);

	                     XRTableCell data= AlphaWebReports.raporteUtil.shtoQelizeNeTabele(94.33f, "" ,String.Format("{0:dd/MM/yyyy}", Convert.ToDateTime(row["DTDOK"])), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, borders, padding);
	                    rr.Cells.Add(data);

	                    XRTableCell kodifikimart= AlphaWebReports.raporteUtil.shtoQelizeNeTabele(123.53f,  "", row["KODARTIKULLI"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
	                    rr.Cells.Add(kodifikimart);

	                    XRTableCell kodKF= AlphaWebReports.raporteUtil.shtoQelizeNeTabele(98.14f, "", row["KODIKF"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
	                    rr.Cells.Add(kodKF);

	                    XRTableCell serialK= AlphaWebReports.raporteUtil.shtoQelizeNeTabele(118.83f, "", row["SERIALI_KRYESOR"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
	                    rr.Cells.Add(serialK);

	                    XRTableCell pr= AlphaWebReports.raporteUtil.shtoQelizeNeTabele(63.67f,  "", row["PR"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borderLast , padding);
	                    rr.Cells.Add(pr);   

	                    xrTable12.Rows.Insert((i + 1), rr);
	                    i++;
			}
		}
	}
}
private void shtoRreshtatNeTabele(XRTable xrTable2)
{
	int i = 0;
	if (dt.Rows.Count > 0)
	{
		for (int j = xrTable2.Rows.Count - 1; j >= 1; j--)
		{
			xrTable2.Rows.RemoveAt(j);
		}
		Font arial = new Font("Century Gothic", 9.00F, FontStyle.Regular);
		PaddingInfo padding = new PaddingInfo(2, 2, 0, 0);
		BorderSide borders = ((BorderSide)((BorderSide.Left | BorderSide.Bottom )));
		BorderSide borderLast = ((BorderSide)((BorderSide.Left | BorderSide.Bottom | BorderSide.Right )));

		foreach (System.Data.DataRow row in dt.Rows)
			{ 
				if(Convert.ToInt32(row["grup1"]) == 1 && Convert.ToInt32(row["grup1"])!= 0)
				{
					XRTableRow rr = new XRTableRow();
					rr.HeightF = 20f;
					XRTableCell nr = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(26.63f, "", (i + 1).ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
					rr.Cells.Add(nr);

					XRTableCell pershkrimi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(265f,  "", row["PERSHKRIMI"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
					rr.Cells.Add(pershkrimi);

					XRTableCell njesia = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(50.15f, "", row["PERSHKRIMNJESIA"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
					rr.Cells.Add(njesia);

					XRTableCell sasia = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(39.95f, "" , row["SASIA"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, borders, padding);
					rr.Cells.Add(sasia);

					XRTableCell cmimi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(82.86f, "" , String.Format("{0:N2}", row["CMIMI"]), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, borders, padding);
					rr.Cells.Add(cmimi);

					XRTableCell vleraPaTvsh = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(79.31f, "" , String.Format("{0:N2}", row["VLEFTAPATVSH"]), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, borders, padding);
					rr.Cells.Add(vleraPaTvsh);

					XRTableCell VleftaETVSH = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(78.26f, "" , String.Format("{0:N2}",  Convert.ToDouble(dt.Rows[i]["TVSH"]) * Convert.ToDouble(dt.Rows[i]["VLEFTAPATVSH"])), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, borders, padding);
					rr.Cells.Add(VleftaETVSH);

					XRTableCell VleftaMeTVSH = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(102.24f, "" , String.Format("{0:N2}", row["VLEFTAMETVSH"]) , arial, Color.Silver, Color.Transparent,TextAlignment.MiddleRight, borderLast , padding);
					rr.Cells.Add(VleftaMeTVSH);

					xrTable2.Rows.Insert((i + 1), rr);
					i++;
				}
              	}
	}
}

